import{_ as a,o,c as l,aw as e}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Декораторы","description":"","frontmatter":{},"headers":[],"relativePath":"common/typescript/class/decorators.md","filePath":"wiki/dev-commit/common/typescript/class/decorators.md"}'),n={name:"common/typescript/class/decorators.md"};function t(p,s,c,r,i,u){return o(),l("div",null,[...s[0]||(s[0]=[e(`<h1 id="декораторы" tabindex="-1">Декораторы <a class="header-anchor" href="#декораторы" aria-label="Permalink to &quot;Декораторы&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Определение</p><ul><li><strong>Декораторы</strong> - являются инструментом декларативного программирования, они позволяют добавить к классам и их членам метаданные и тем самым изменить их поведение без изменения их кода</li></ul></div><ul><li>Декораторы представляют собой функции</li><li>Декораторы используют форму <code>@expression</code>, т.е. при использовании ставится символ <code>@</code> перед именем декоратора. Хотя по сути expression может быть любая функция. Эта функция будет вызвана в процессе выполнения программы, причем вызывающий код добавит аргументы с информацией о том объекте, который был задекорирован.</li><li>Важно, что декоратор - это лишь функция. При использовании среда исполнения сначала вызовет функцию-декоратор, и только потом будет выполнен основной сценарий объекта (если код декоратора содержит этот вызов). При наличии нескольких декораторов у одного объявления их выражения вычисляются сверху вниз, а сами декораторы вызываются снизу вверх.</li><li>Декоратор для функции, свойства или параметра функции можно применить только внутри некоего класса. В настоящее время компилятор TypeScript не позволит применить декоратор для функции, которая написана вне класса.</li></ul><h3 id="к-каким-элементам-можно-добавить-декораторы" tabindex="-1">К каким элементам можно добавить декораторы <a class="header-anchor" href="#к-каким-элементам-можно-добавить-декораторы" aria-label="Permalink to &quot;К каким элементам можно добавить декораторы&quot;">​</a></h3><ul><li>Классы</li><li>Методы</li><li>Методы доступа (Геттеры и Сеттеры)</li><li>Свойства</li><li>Параметры</li></ul><h2 id="установка-и-настроика" tabindex="-1">Установка и настройка <a class="header-anchor" href="#установка-и-настроика" aria-label="Permalink to &quot;Установка и настройка&quot;">​</a></h2><ul><li>Декораторы являются экспериментальной функциональностью языка TypeScript (на 2021 год), поэтому при компиляции следует указывать параметр <em>experimentalDecorators</em> в файле <em>tsconfig.json</em></li></ul><div class="language-json"><button title="Скопировать код" class="copy"></button><span class="lang">json</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">{</span></span>
<span class="line"><span style="color:#E45649;">  &quot;compilerOptions&quot;</span><span style="color:#383A42;">: {</span></span>
<span class="line"><span style="color:#E45649;">    &quot;module&quot;</span><span style="color:#383A42;">: </span><span style="color:#50A14F;">&quot;commonjs&quot;</span><span style="color:#383A42;">,</span></span>
<span class="line"><span style="color:#E45649;">    &quot;declaration&quot;</span><span style="color:#383A42;">: </span><span style="color:#0184BC;">true</span><span style="color:#383A42;">,</span></span>
<span class="line"><span style="color:#E45649;">    &quot;removeComments&quot;</span><span style="color:#383A42;">: </span><span style="color:#0184BC;">true</span><span style="color:#383A42;">,</span></span>
<span class="line"><span style="color:#E45649;">    &quot;emitDecoratorMetadata&quot;</span><span style="color:#383A42;">: </span><span style="color:#0184BC;">true</span><span style="color:#383A42;">,</span></span>
<span class="line"><span style="color:#E45649;">    &quot;experimentalDecorators&quot;</span><span style="color:#383A42;">: </span><span style="color:#0184BC;">true</span><span style="color:#383A42;">,</span></span>
<span class="line"><span style="color:#E45649;">    &quot;target&quot;</span><span style="color:#383A42;">: </span><span style="color:#50A14F;">&quot;es2017&quot;</span></span>
<span class="line"><span style="color:#383A42;">  }</span></span>
<span class="line"><span style="color:#383A42;">}</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><ul><li>С TypeScript 5.0 стандартные декораторы (ECMAScript) работают без флага. <code>experimentalDecorators</code> нужен для старой (экспериментальной) реализации, в том числе для декораторов параметров и <code>emitDecoratorMetadata</code></li></ul></div>`,10)])])}const y=a(n,[["render",t]]);export{m as __pageData,y as default};
